I have an even simpler example, hope it helps:

```rust
use bevy::{prelude::*, ui::RelativeCursorPosition};

#[derive(Component)]
pub struct Orange;

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .add_systems(Startup, spawn_ui)
        .add_systems(Update, (print_interactions, toggle_visibility))
        .run();
}

fn spawn_ui(mut commands: Commands) {
    commands.spawn(Camera2dBundle::default());

    let button_1 = commands
        .spawn(ButtonBundle {
            style: Style {
                width: Val::Px(100.),
                height: Val::Px(100.),
                margin: UiRect::all(Val::Auto),
                justify_content: JustifyContent::Center,
                ..Default::default()
            },
            background_color: BackgroundColor::from(Color::CYAN),
            ..Default::default()
        })
        .id();

    commands
        .entity(button_1)
        .insert(RelativeCursorPosition::default());

    let button_2 = commands
        .spawn(ButtonBundle {
            style: Style {
                width: Val::Px(200.),
                height: Val::Px(200.),
                top: Val::Px(20.),
                left: Val::Px(20.),
                position_type: PositionType::Absolute,
                ..Default::default()
            },
            background_color: BackgroundColor::from(Color::ORANGE),
            ..Default::default()
        })
        .id();

    commands
        .entity(button_2)
        .insert((RelativeCursorPosition::default(), Orange));

    commands.entity(button_1).add_child(button_2);
}

fn print_interactions(nodes: Query<(&RelativeCursorPosition, &ViewVisibility), With<Node>>) {
    for (cursor_position, visibility) in &nodes {
        if visibility.get() && cursor_position.mouse_over() {
            println!("over");
        }
    }
}

fn toggle_visibility(
    mut orange_node: Query<&mut Style, With<Orange>>,
    input: Res<ButtonInput<KeyCode>>,
) {
    if input.just_pressed(KeyCode::KeyP) {
        let mut style = orange_node.single_mut();
        if style.display == Display::Flex {
            style.display = Display::None;
        } else {
            style.display = Display::Flex;
        }
    }
}
````

When both nodes are visible, `"over"` is printed correctly (when the mouse is over either node and not anywhere else), but as soon as the orange node is hidden, `"over"` is: 
* correctly printed when over the cyan node,
* correctly not printed when there was previously the orange node, 
* BUT it's also printed if your cursor is in the region from the top left corner of the window, to the top left corner of the cyan node.
